export const areaHistories=[
 {names:['Hurrian Kingdoms','Hurrian kingdoms','Hurrians'],start:-3000,end:-2401,summary:'Хурриты — языковая и культурная общность, а не название единого государства. Для ранней части III тысячелетия до н. э. нельзя уверенно перечислить её царства, правителей и политические границы.',society:'Уркеш, современный Телль-Мозан на севере Сирии, — ключевой город для изучения хурритской истории III тысячелетия. Хурритская принадлежность других ранних центров значительно менее определённа. Название «хурритские царства» на обзорной карте не доказывает существование единой державы в выбранном году.',sources:[{title:'Уркеш и хурриты · археологическая экспедиция',url:'https://urkesh.org/urkeshpublic/hurrians.htm'}]},
 {names:['Hurrian Kingdoms','Hurrian kingdoms','Hurrians','Urkesh','Urkish'],start:-2400,end:-2000,summary:'Уркеш — самостоятельный городской центр хурритского мира на севере Месопотамии. Его нельзя считать столицей государства, объединявшего всех хурритов.',society:'В Уркеше существовали местная царская власть и собственная городская традиция. Археологи не находят оснований считать его империю больше города-государства с обширной округой.',beliefs:'Храмовые посвящения из Уркеша отражают местную религиозную жизнь и связи с южной Месопотамией. Бронзовая фигурка льва, датируемая примерно 2200–2100 годами до н. э., связана с закладкой храма; это свидетельство конца тысячелетия, а не всего его раннего периода.',sources:[{title:'Уркеш и хурриты · археологическая экспедиция',url:'https://urkesh.org/urkeshpublic/hurrians.htm'},{title:'Хурритский закладной лев, 2200–2100 до н. э. · Метрополитен-музей',url:'https://www.metmuseum.org/art/collection/search/329078'}]},
 {names:['Mitanni','Mittani'],start:-1500,end:-1241,summary:'Митанни — царство хурритского мира позднего бронзового века в Северной Месопотамии и Сирии. Оно возникло значительно позже ранних хурритских центров III тысячелетия до н. э.',society:'Царская власть Митанни связывала разные города и местные общества. Распространение хурритского языка и культуры не означает, что всё население имело одинаковую идентичность.',economy:'Нузи был одним из городских центров Митанни в XV–XIV веках до н. э. Его изделия из стекловидного фаянса показывают развитое ремесло; похожие сосуды находят и в Египте.',sources:[{title:'Митанни и Сирия позднего бронзового века · Метрополитен-музей',url:'https://www.metmuseum.org/essays/ugarit'},{title:'Нузи и ремесло Митанни · Метрополитен-музей',url:'https://www.metmuseum.org/art/collection/search/544860'}]},

 {names:['Western Roman Empire'],start:395,end:476,summary:'Западная часть Римской империи сохраняет императорский двор, армию, города и провинциальное управление. В V веке её власть сокращается; на прежних имперских землях усиливаются новые королевства.',society:'Императорская власть опирается на военных командиров и провинциальные элиты. Горожане, земледельцы и крупные землевладельцы находятся в разных правовых и экономических условиях.',economy:'Земледелие, налоги, ремесло и средиземноморские перевозки поддерживают государство. Войны и утрата провинций нарушают эти связи.',beliefs:'Христианские церкви играют заметную общественную роль; сохраняются разные христианские направления, иудейские общины и местные практики.',sources:[{title:'Позднеримский и византийский мир · Метрополитен-музей',url:'https://www.metmuseum.org/essays/byzantium-ca-330-1453'}]},
 {names:['Roman Republic','Rome'],start:-509,end:-28,summary:'Римская республика — общество гражданских институтов, социальной иерархии и военной экспансии. Рим постепенно превращается из италийского центра в средиземноморскую державу.',society:'Сенат, выборные магистраты и народные собрания участвуют в управлении. Возможности влиять на политику зависят от статуса, богатства и гражданства; значительную роль играет рабство.',economy:'Земледелие, военная добыча, торговля и рабский труд поддерживают растущую державу. Завоевания увеличивают богатство элит и социальные противоречия.',beliefs:'Гражданские и домашние культы связывают ритуал с общественной жизнью. Рим включается в более широкий греческий и италийский религиозный мир.',sources:[{title:'Римская республика · Метрополитен-музей',url:'https://www.metmuseum.org/de/essays/the-roman-republic'}]},
 {names:['Parthia','Parthian Empire'],start:-247,end:224,summary:'Парфянская держава Аршакидов связывает Иран и Месопотамию с соседними областями. Она соперничает с Римом и участвует в обмене между средиземноморским и азиатскими мирами.',society:'Царская власть взаимодействует с влиятельными знатными родами, местными правителями и городами. Политическое единство не означает культурного единообразия.',economy:'Земледелие, города, ремесло и дальний обмен поддерживают хозяйство. Ктесифон становится важной царской резиденцией.',beliefs:'Местные иранские и месопотамские традиции взаимодействуют с эллинистическим наследием и другими религиозными общинами.',sources:[{title:'Парфянская империя · Метрополитен-музей',url:'https://www.metmuseum.org/de/essays/the-parthian-empire-247-b-c-224-a-d'}]},
 {names:['Meroe','Kush'],start:-300,end:350,summary:'Мероэ — один из главных центров царства Куш. Дворцы, храмы и царские погребения показывают самостоятельную нубийскую политическую и художественную традицию.',society:'Царская власть, храмовые институты и местные сообщества участвуют в устройстве государства. Правители и правительницы оставляют собственные памятники власти.',economy:'Земледелие, скотоводство, ремесло и обмен связывают нильские и внутренние африканские пространства.',beliefs:'Местные божества и культы взаимодействуют с египетскими традициями; погребальные комплексы выражают царскую сакральность.',sources:[{title:'Памятники острова Мероэ · ЮНЕСКО',url:'https://whc.unesco.org/en/list/1336/'}]},
 {names:['Maya','Maya city-states','Maya chiefdoms and states'],start:250,end:900,summary:'Классический мир майя состоит из многих соперничающих и сотрудничающих городских государств. Паленке, Тикаль, Копан и Калакмуль — разные центры, а не столицы единой империи.',society:'Династические правители и элиты соперничают за престиж и власть. Надписи, монументы и церемонии закрепляют память о правящих домах.',economy:'Земледелие, ремесло и обмен связывают сельские поселения и города.',beliefs:'Календарные циклы, божества, предки и царские церемонии имеют важное значение. Традиции майя не исчезают с окончанием классического периода.',sources:[{title:'Мир майя · Национальный музей американских индейцев',url:'https://maya.nmai.si.edu/the-maya/maya-world'}]},
 {names:['Empire of Ghana','Ghana'],start:300,end:1200,summary:'Средневековая Гана — одно из влиятельных государств западного Сахеля. Её не следует отождествлять с современной Республикой Гана.',society:'Политические центры связаны с местными обществами и транссахарскими контактами.',economy:'Торговые пути соединяют Сахель с Сахарой и другими регионами. Города и ремёсла участвуют в дальнем обмене.',beliefs:'Местные традиции взаимодействуют с исламом, распространяющимся по торговым и политическим сетям.',sources:[{title:'Государства Сахеля · Метрополитен-музей',url:'https://www.metmuseum.org/exhibitions/sahel-art-empire-sahara'}]},
 {names:['Mali'],start:1230,end:1600,summary:'Держава Мали — один из крупных политических миров средневекового Сахеля. Она связана с городами, земледельческими общинами и транссахарским обменом.',society:'Власть правителей взаимодействует с региональными элитами и разнообразным населением.',economy:'Дальняя торговля, города, ремесло и местное производство связывают Сахель с соседними мирами.',beliefs:'Исламские институты и учёность сосуществуют с местными религиозными традициями.',sources:[{title:'Искусство и государства Сахеля · Метрополитен-музей',url:'https://www.metmuseum.org/exhibitions/sahel-art-empire-sahara'}]},
 {names:['Songhai'],start:1464,end:1591,summary:'Сонгай — влиятельная держава западного Сахеля, связанная с долиной Нигера и городами дальнего обмена.',society:'Государственная власть соединяет различные города и местные общества.',economy:'Торговые сети и местное производство поддерживают города и региональные связи.',beliefs:'Мусульманская учёность и институты имеют большое значение; население сохраняет религиозное разнообразие.',sources:[{title:'Искусство и государства Сахеля · Метрополитен-музей',url:'https://www.metmuseum.org/exhibitions/sahel-art-empire-sahara'}]}
];
export function historyForArea(feature,year){return areaHistories.find(h=>h.start<=year&&year<=h.end&&h.names.includes(feature.properties.name))||null;}

// A point without a polity gets a regional overview. A named polity never does.
export function narrativeForArea(feature,year,profile,context,locale='ru'){
 if(feature.properties.mode==='context')return {summary:context.summary,society:context.life,beliefs:context.beliefs,sources:context.sources,scope:'Региональный обзор'};
 const entry=historyForArea(feature,year);
 if(entry)return {...entry,scope:'Историческое общество'};
 return {summary:profile?.description?.[locale]?.replace(/\u00ad/g,''),sources:[],scope:'Краткий профиль'};
}
